<?php foreach($orders as$o):$orderOutputs=$productionLines['outputs'][$o['id']]??[];$orderInputs=$productionLines['inputs'][$o['id']]??[];$canValidate=!empty($o['flow_managed'])&&$o['status']==='results_submitted'&&$canOperate&&Auth::can('butchery','validate',$site);?>
<section id="production-detail-<?=e($o['id'])?>" class="entity-modal workspace-entity-modal feed-editor production-detail" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="production-detail-title-<?=e($o['id'])?>">
<header><div><p class="page-kicker">BOUCHERIE · TRANSFORMATION</p><h2 id="production-detail-title-<?=e($o['id'])?>">Détails de la transformation</h2><p><?=e($o['order_number'])?></p></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer les détails">×</button></header>
<div class="feed-form-body"><span class="status-badge ui-status ui-status--<?=e($statusTone($o['status']))?>"><?=e($productionStatuses[$o['status']]??$o['status'])?></span>
<dl class="production-detail-summary"><?php foreach(['Fiche'=>$o['recipe_name'],'Date'=>date('d/m/Y',strtotime($o['production_date'])),'Enregistré par'=>$o['author']?:'—','Matière'=>$kg($o['actual_input_kg']).' kg','Produits obtenus'=>$kg((float)$o['output_kg']+(float)$o['co_product_kg']).' kg','Pertes'=>$kg($o['loss_kg']).' kg'] as$label=>$value):?><div><dt><?=e($label)?></dt><dd><?=e($value)?></dd></div><?php endforeach;?></dl>
<?php if($o['status']==='results_submitted'):?><p class="livestock-guide"><?php if(!empty($o['flow_managed'])):?>La matière est réservée. <?php endif;?>Les produits deviennent disponibles après validation.</p><?php elseif($o['status']==='cancelled'):?><p class="livestock-guide">Transformation annulée. Ces quantités sont exclues des indicateurs de production.</p><?php endif;?>
<h3>Matières et lots utilisés</h3><div class="table-responsive"><table class="enterprise-table production-detail-table" data-datatable="false" aria-label="Matières utilisées"><thead><tr><th scope="col">Produit</th><th scope="col">Lot source</th><th scope="col" class="num">Quantité (kg)</th></tr></thead><tbody><?php foreach($orderInputs as$input):?><tr><td><?=e($input['item_name'])?></td><td><?=e($input['lot_number']?:'Sans lot')?></td><td class="num"><?=$kg($input['quantity_kg'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$orderInputs):?><p>Aucune matière enregistrée pour le moment.</p><?php endif;?>
<h3>Produits et répartition <?=$o['status']==='validated'?'à la validation':'prévue'?></h3><div class="table-responsive"><table class="enterprise-table production-detail-table" data-datatable="false" aria-label="Produits obtenus et répartition"><thead><tr><th scope="col">Produit</th><th scope="col" class="num">Obtenu (kg)</th><th scope="col" class="num">Au froid (kg)</th><th scope="col">Au comptoir</th><th scope="col">DLC du produit</th></tr></thead><tbody><?php foreach($orderOutputs as$line):$a=$allocations[$line['id']]??null;?><tr><td><?=e($line['item_name'])?></td><td class="num"><?=$kg($line['quantity_kg'])?></td><td class="num"><?=$kg((float)$line['quantity_kg']-(float)($a['counter_quantity_kg']??0))?></td><td><?=$a?e($kg($a['counter_quantity_kg']).' kg · '.$a['counter_name']):'—'?></td><td><?=e(date('d/m/Y',strtotime($line['expiry_date'])))?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$orderOutputs):?><p>Aucun résultat enregistré pour le moment.</p><?php endif;?>
<?php if(empty($o['flow_managed'])):?><p><a class="btn-secondary" href="<?=e(base_url('butchery/history/production'))?>">Consulter le dossier de fabrication</a></p><?php endif;?>
<?php if(!empty($o['flow_managed'])&&$o['status']==='results_submitted'&&$canOperate&&Auth::can('butchery','delete',$site)):$action='butchery/flow/transformations/'.$o['id'].'/cancel';?><details class="production-cancel"><summary>Annuler cette transformation</summary><?php require __DIR__.'/cancel_form.php';?></details><?php endif;?>
</div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button>
<?php if($canValidate):?><form id="production-validate-<?=e($o['id'])?>" method="post" action="<?=e(base_url('butchery/flow/transformations/'.$o['id'].'/validate'))?>" class="enterprise-form production-detail-validation" data-flow-form data-confirm="Valider les produits obtenus et leur répartition entre froid et comptoir ?"><?=csrf_field()?><input type="hidden" name="_flow_return" value="<?=e($returnPath)?>"><input type="hidden" name="operation_key" value="<?=e(bin2hex(random_bytes(16)))?>"><p class="app-alert app-alert-error" data-feed-error role="alert" hidden></p><button type="submit" class="btn-primary"><i class="bi bi-check2" aria-hidden="true"></i> Valider</button></form><?php endif;?>
</footer></section><?php endforeach;?>
